CREATE SCHEMA identity;
CREATE SCHEMA workspace;
CREATE SCHEMA delivery;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
CREATE TABLE workspace.organisations(id uuid PRIMARY KEY, name text NOT NULL, slug text UNIQUE NOT NULL);
CREATE TABLE workspace.branches(tenant_id uuid NOT NULL REFERENCES workspace.organisations(id), id uuid NOT NULL, name text NOT NULL, PRIMARY KEY(tenant_id,id));
CREATE TABLE identity.users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL CHECK(email = lower(email)), display_name text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE identity.memberships(tenant_id uuid NOT NULL REFERENCES workspace.organisations(id), user_id uuid NOT NULL REFERENCES identity.users(id), branch_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('owner','staff','viewer')), active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,user_id), FOREIGN KEY(tenant_id,branch_id) REFERENCES workspace.branches(tenant_id,id));
CREATE TABLE identity.challenges(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES identity.users(id), code_hash text NOT NULL, expires_at timestamptz NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5), consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX challenges_user_time ON identity.challenges(user_id,created_at);
CREATE TABLE identity.request_limits(email_hash text NOT NULL, requested_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX request_limits_lookup ON identity.request_limits(email_hash,requested_at);
CREATE TABLE identity.sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES identity.users(id), expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspace.tasks(tenant_id uuid NOT NULL REFERENCES workspace.organisations(id), id uuid NOT NULL, branch_id uuid NOT NULL, assignee_id uuid NOT NULL, template text NOT NULL CHECK(template='review_inventory'), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')), idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,idempotency_key), FOREIGN KEY(tenant_id,branch_id) REFERENCES workspace.branches(tenant_id,id), FOREIGN KEY(tenant_id,assignee_id) REFERENCES identity.memberships(tenant_id,user_id));
CREATE INDEX tasks_assignee ON workspace.tasks(tenant_id,assignee_id,created_at DESC);
CREATE TABLE workspace.evidence(tenant_id uuid NOT NULL, id uuid NOT NULL, sequence bigint NOT NULL, task_id uuid NOT NULL, actor_id uuid NOT NULL, action text NOT NULL CHECK(action IN ('task.created','task.closed')), previous_hash text NOT NULL, event_hash text NOT NULL, occurred_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,sequence), FOREIGN KEY(tenant_id,task_id) REFERENCES workspace.tasks(tenant_id,id), FOREIGN KEY(tenant_id,actor_id) REFERENCES identity.memberships(tenant_id,user_id));
CREATE TABLE workspace.outbox(tenant_id uuid NOT NULL, id uuid NOT NULL, task_id uuid NOT NULL, recipient text NOT NULL, subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','sent','failed','cancelled')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3), lease_token uuid, lease_until timestamptz, available_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,task_id), FOREIGN KEY(tenant_id,task_id) REFERENCES workspace.tasks(tenant_id,id));
CREATE INDEX outbox_due ON workspace.outbox(tenant_id,status,available_at);
CREATE TABLE delivery.login_jobs(id uuid PRIMARY KEY REFERENCES identity.challenges(id), recipient text NOT NULL, subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','sent','failed')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3), lease_token uuid, lease_until timestamptz, available_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE delivery.mailbox(message_id uuid PRIMARY KEY, recipient text NOT NULL CHECK(recipient LIKE '%@demo.sahmati.test'), subject text NOT NULL, body text NOT NULL, delivered_at timestamptz NOT NULL DEFAULT now());
GRANT USAGE ON SCHEMA identity,workspace,delivery TO sahmati_app,sahmati_worker;
GRANT SELECT ON identity.users,identity.memberships TO sahmati_app,sahmati_worker;
GRANT SELECT,INSERT,UPDATE ON identity.challenges,identity.sessions,identity.request_limits TO sahmati_app;
GRANT SELECT,INSERT ON delivery.login_jobs TO sahmati_app;
GRANT SELECT ON delivery.mailbox TO sahmati_app;
GRANT SELECT,UPDATE ON delivery.login_jobs TO sahmati_worker;
GRANT SELECT ON identity.challenges TO sahmati_worker;
GRANT SELECT,INSERT ON delivery.mailbox TO sahmati_worker;
GRANT SELECT ON workspace.organisations,workspace.branches TO sahmati_app,sahmati_worker;
GRANT SELECT,INSERT,UPDATE ON workspace.tasks TO sahmati_app;
GRANT SELECT ON workspace.tasks TO sahmati_worker;
GRANT SELECT,INSERT ON workspace.evidence TO sahmati_app;
GRANT SELECT,INSERT ON workspace.outbox TO sahmati_app;
GRANT SELECT,UPDATE ON workspace.outbox TO sahmati_worker;
